 Ryokou","dates":[{"region":"JP","date":"1998-03-26","precision":"day"}],"publishers":["Q1372258"]}]},{"qid":null,"title":"Zoku Mikagura Shōjo Tanteidan ~Kanketsuhen~","title_merge":true,"first_release":{"date":"1999-10-07","precision":"day"},"developers":["Q2408214"],"releases":[{"zone":"NTSC-J","national":null,"edition":"standard","title":"Zoku Mikagura Shōjo Tanteidan ~Kanketsuhen~","dates":[{"region":"JP","date":"1999-10-07","precision":"day"}],"publishers":["name:humanentertainment"]}]},{"qid":"Q1974823","title":"Zoop","title_merge":true,"first_release":{"date":"1995-11-20","precision":"day"},"developers":["name:hookstone"],"releases":[{"zone":"PAL","national":null,"edition":"standard","title":"Zoop","dates":[{"region":"europe","date":"1996-11-22","precision":"day"}],"publishers":["Q3088127"]},{"zone":"NTSC-U","national":null,"edition":"standard","title":"Zoop","dates":[{"region":"north-america","date":"1995-11-20","precision":"day"}],"publishers":["Q3088127"]}]},{"qid":null,"title":"Zork I: The Great Underground Empire","title_merge":true,"first_release":{"date":"1996-03-15","precision":"day"},"developers":["Q7500035"],"releases":[{"zone":"NTSC-J","national":null,"edition":"standard","title":"Zork I: The Great Underground Empire","dates":[{"region":"JP","date":"1996-03-15","precision":"day"}],"publishers":["name:shoeisha"]}]},{"qid":null,"title":"Zutto Issho: With me Everytime","title_merge":true,"first_release":{"date":"1998-03-12","precision":"day"},"developers":["name:beyondinteractive"],"releases":[{"zone":"NTSC-J","national":null,"edition":"standard","title":"Zutto Issho: With me Everytime","dates":[{"region":"JP","date":"1998-03-12","precision":"day"}],"publishers":["Q1365614"]}]},{"qid":null,"title":"ZXE-D: Legend of Plasmalite","title_merge":true,"first_release":{"date":"1996-12-20","precision":"day"},"developers":[],"releases":[{"zone":"NTSC-J","national":null,"edition":"standard","title":"ZXE-D: Legend of Plasmalite","dates":[{"region":"JP","date":"1996-12-20","precision":"day"}],"publishers":["Q507269"]}]}]}$wikipedia$::jsonb;
  ps1       bigint := (select id from public.platform where short_name = 'PS1');
  company   jsonb;
  g         jsonb;
  r         jsonb;
  d         jsonb;
  k         text;
  v_game    bigint;
  v_release bigint;
  v_pal     bigint;
  v_zone    public.video_zone;
  companies jsonb := '{}';
begin
  -- 1. Sociétés
  for company in select value from jsonb_array_elements(data -> 'companies') loop
    companies := companies || jsonb_build_object(
      company ->> 'key', pg_temp.company_id(company ->> 'qid', company ->> 'name'));
  end loop;

  for g in select value from jsonb_array_elements(data -> 'games') loop
    -- 2. Jeu : par identifiant Wikidata, sinon par titre normalisé, sinon création
    v_game := null;
    if g ->> 'qid' is not null then
      select id into v_game from public.game where wikidata_id = g ->> 'qid';
    end if;
    if v_game is null and (g ->> 'title_merge')::boolean then
      select id into v_game from public.game
      where title_key = public.normalize_name(g ->> 'title')
        and (wikidata_id is null or g ->> 'qid' is null)
      order by id
      limit 1;
      if v_game is not null and g ->> 'qid' is not null then
        update public.game set wikidata_id = g ->> 'qid' where id = v_game;
      end if;
    end if;
    if v_game is null then
      insert into public.game (title, wikidata_id)
      values (g ->> 'title', g ->> 'qid')
      returning id into v_game;
    end if;

    if g -> 'first_release' <> 'null'::jsonb then
      update public.game
      set first_release_date = (g -> 'first_release' ->> 'date')::date,
          first_release_precision = (g -> 'first_release' ->> 'precision')::public.date_precision
      where id = v_game and first_release_date is null;
    end if;

    for k in select jsonb_array_elements_text(g -> 'developers') loop
      insert into public.game_developer (game_id, company_id)
      values (v_game, (companies ->> k)::bigint)
      on conflict do nothing;
    end loop;

    -- 3. Sorties
    v_pal := null;
    for r in select value from jsonb_array_elements(g -> 'releases') loop
      v_zone := (r ->> 'zone')::public.video_zone;
      v_release := null;

      if r ->> 'edition' = 'platinum' then
        select id into v_release from public.release
        where game_id = v_game and platform_id = ps1 and zone = 'PAL'
          and edition_type = 'reissue' and edition_name = 'Platinum'
        order by id limit 1;
        if v_release is null then
          insert into public.release (game_id, platform_id, reissue_of, local_title, zone, edition_type, edition_name)
          values (v_game, ps1, v_pal, r ->> 'title', 'PAL', 'reissue', 'Platinum')
          returning id into v_release;
        end if;

      elsif r ->> 'national' is not null then
        select id into v_release from public.release
        where game_id = v_game and platform_id = ps1 and zone = v_zone
          and edition_type = 'standard'
          and public.normalize_name(local_title) = public.normalize_name(r ->> 'title')
        order by id limit 1;
        if v_release is null then
          insert into public.release (game_id, platform_id, local_title, zone)
          values (v_game, ps1, r ->> 'title', v_zone)
          returning id into v_release;
        end if;

      else
        -- Sortie de base de la zone : existante, ou sortie « à compléter » à réutiliser
        select id into v_release from public.release
        where game_id = v_game and platform_id = ps1 and zone = v_zone and edition_type = 'standard'
        order by id limit 1;
        if v_release is null then
          select rel.id into v_release from public.release rel
          where rel.game_id = v_game and rel.platform_id = ps1 and rel.zone is null
            and rel.edition_type = 'standard' and rel.product_code is null
            and not exists (select 1 from public.collection_item ci where ci.release_id = rel.id)
            and not exists (select 1 from public.image i where i.release_id = rel.id)
          order by rel.id limit 1;
          if v_release is not null then
            update public.release set zone = v_zone, local_title = r ->> 'title' where id = v_release;
          else
            insert into public.release (game_id, platform_id, local_title, zone)
            values (v_game, ps1, r ->> 'title', v_zone)
            returning id into v_release;
          end if;
        end if;
        if v_zone = 'PAL' then v_pal := v_release; end if;
      end if;

      for d in select value from jsonb_array_elements(r -> 'dates') loop
        insert into public.release_region (release_id, region_id, release_date, date_precision)
        select v_release, rg.id, (d ->> 'date')::date, (d ->> 'precision')::public.date_precision
        from public.region rg where rg.code = d ->> 'region'
        on conflict do nothing;
      end loop;

      for k in select jsonb_array_elements_text(r -> 'publishers') loop
        insert into public.release_company (release_id, company_id, role)
        values (v_release, (companies ->> k)::bigint, 'publisher')
        on conflict do nothing;
      end loop;
    end loop;
  end loop;
end;
$import$;

drop function pg_temp.company_id(text, text);
